class Solution {
  public int maxTotalReward(int[] rewardValues) {
    java.util.Arrays.sort(rewardValues);
    int limit = 0;
    for (int x : rewardValues) limit = Math.max(limit, x);
    boolean[] can = new boolean[2 * limit + 1];
    can[0] = true;
    int best = 0;
    for (int x : rewardValues) {
      for (int s = Math.min(best, x - 1); s >= 0; s--) {
        if (can[s]) can[s + x] = true;
      }
      best = Math.max(best, 2 * x - 1);
      while (best >= 0 && !can[best]) best--;
    }
    for (int s = can.length - 1; s >= 0; s--) if (can[s]) return s;
    return 0;
  }
}
